public async Task<Dictionary<int, int>> GetViewsByBlogIdAsync(
    BlogContext context,
    string searchTerm,
    CancellationToken cancellationToken = default)
{
    var totals = from p in context.Posts
                 where p.Title.Contains(searchTerm)
                 group p.Views by p.BlogId into g
                 select new { BlogId = g.Key, TotalViews = g.Sum() };

    var rows = await totals.ToListAsync(cancellationToken);

    return rows.ToDictionary(r => r.BlogId, r => r.TotalViews);
}
```

